package mz.co.aprendaacodar.question.service;
import mz.co.aprendaacodar.common.response.PageResponse;import org.springframework.data.domain.Pageable;
import mz.co.aprendaacodar.common.enums.Enums.*;import mz.co.aprendaacodar.common.exception.*;import mz.co.aprendaacodar.course.entity.Lesson;import mz.co.aprendaacodar.course.repository.LessonRepository;import mz.co.aprendaacodar.enrollment.repository.EnrollmentRepository;import mz.co.aprendaacodar.question.dto.QuestionDtos.*;import mz.co.aprendaacodar.question.entity.*;import mz.co.aprendaacodar.question.repository.*;import mz.co.aprendaacodar.user.entity.User;import mz.co.aprendaacodar.user.repository.UserRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class QuestionService {
 private final QuestionRepository questions;private final QuestionReplyRepository replies;private final LessonRepository lessons;private final UserRepository users;private final EnrollmentRepository enrollments;
 public QuestionService(QuestionRepository q,QuestionReplyRepository r,LessonRepository l,UserRepository u,EnrollmentRepository e){questions=q;replies=r;lessons=l;users=u;enrollments=e;}
 @Transactional public Response ask(UUID student,UUID lessonId,String content){Lesson l=lesson(lessonId);User s=user(student);if(s.getRole()!=UserRole.STUDENT||s.getStatus()!=UserStatus.ACTIVE||!enrollments.existsByStudentIdAndCourseIdAndStatus(student,l.getCourse().getId(),EnrollmentStatus.ACTIVE))throw new ForbiddenOperationException("É necessário ter acesso à aula para colocar dúvidas.");return map(questions.save(new LessonQuestion(l,s,content.trim())));}
 @Transactional(readOnly=true) public PageResponse<Response> byLesson(UUID actor,UUID lessonId,Pageable pageable){Lesson l=lesson(lessonId);ensureCanView(actor,l);return PageResponse.from(questions.findAllByLessonIdOrderByCreatedAt(lessonId,pageable),this::map);}
 @Transactional(readOnly=true) public Response get(UUID actor,UUID id){LessonQuestion q=find(id);ensureCanView(actor,q.getLesson());return map(q);}
 @Transactional public Response reply(UUID actor,UUID id,String content){LessonQuestion q=find(id);ensureCanManage(actor,q.getLesson());if(q.getStatus()==QuestionStatus.CLOSED)throw new BusinessException("A dúvida está encerrada.");replies.save(new QuestionReply(q,user(actor),content.trim()));q.answered();return map(q);}
 @Transactional public void close(UUID actor,UUID id){LessonQuestion q=find(id);ensureCanManage(actor,q.getLesson());q.close();}
 private void ensureCanView(UUID actor,Lesson l){User u=user(actor);if(u.getRole()==UserRole.ADMIN)return;if(u.getRole()==UserRole.TEACHER&&l.getCourse().getTeacher().getId().equals(actor))return;if(u.getRole()==UserRole.STUDENT&&enrollments.existsByStudentIdAndCourseIdAndStatus(actor,l.getCourse().getId(),EnrollmentStatus.ACTIVE))return;throw new ForbiddenOperationException("Não pode consultar dúvidas desta aula.");}
 private void ensureCanManage(UUID actor,Lesson l){User u=user(actor);if(u.getRole()!=UserRole.ADMIN&&(u.getRole()!=UserRole.TEACHER||!l.getCourse().getTeacher().getId().equals(actor)))throw new ForbiddenOperationException("Apenas o professor responsável ou um administrador pode responder.");}
 private User user(UUID id){return users.findById(id).orElseThrow(()->new ResourceNotFoundException("Utilizador não encontrado."));}private Lesson lesson(UUID id){return lessons.findById(id).orElseThrow(()->new ResourceNotFoundException("Aula não encontrada."));}private LessonQuestion find(UUID id){return questions.findById(id).orElseThrow(()->new ResourceNotFoundException("Dúvida não encontrada."));}
 private Response map(LessonQuestion q){List<ReplyResponse> rr=replies.findAllByQuestionIdOrderByCreatedAt(q.getId()).stream().map(r->new ReplyResponse(r.getId(),r.getAuthor().getId(),r.getAuthor().getFirstName()+" "+r.getAuthor().getLastName(),r.getContent(),r.getCreatedAt())).toList();return new Response(q.getId(),q.getLesson().getId(),q.getStudent().getId(),q.getStudent().getFirstName()+" "+q.getStudent().getLastName(),q.getContent(),q.getStatus(),rr,q.getCreatedAt());}
}
